import { useGSAP } from "@gsap/react";
import gsap from "gsap";
import { SlowMo } from "gsap/EasePack";
import React, { useRef } from "react";

gsap.registerPlugin(SlowMo);

export default function ClipPathTransition() {
  const container = useRef(null);

  const turtleTl = useRef<gsap.core.Timeline | null>(null);

  useGSAP(
    () => {
      gsap
        .timeline({ repeat: -1, repeatDelay: 1, yoyo: true })
        .from("#bird rect", {
          scaleY: 0,
          scaleX: 0,
          transformOrigin: "50% 100%",

          ease: "power1.out",
          stagger: { amount: 0.3, from: "start" },
        })
        .to("#bird rect", {
          scaleX: 0,
          transformOrigin: "100% 50%",

          ease: "power1.in",
          stagger: { amount: 0.3, from: "center" },
        });

      turtleTl.current = gsap
        .timeline({ paused: true })
        .set("#turtle image", { opacity: 1 })
        .from("#turtle ellipse", {
          scale: 0,

          transformOrigin: "50% 50%",
          ease: "back(1)",
        })
        .from(
          "#turtle image",
          {
            scale: 1.2,
            transformOrigin: "50% 50%",
            ease: "power1.out",
          },
          0,
        );
    },
    { scope: container },
  );

  function handleMouseEnter(): void {
    turtleTl.current?.play();
  }

  function handleMouseLeave(): void {
    turtleTl.current?.reversed(true);
  }

  return (
    <div ref={container} style={{ display: "flex", gap: 30 }}>
      <svg
        id="bird"
        xmlns="http://www.w3.org/2000/svg"
        viewBox="0 0 500 333"
        style={{ background: "black" }}
        width={500}
        height={500}
      >
        <defs>
          <clipPath id="clip-bird">
            <rect
              width={499}
              height={50}
              style={{
                fill: "rgb(216, 216, 216)",
                stroke: "rgb(0, 0, 0)",
                strokeWidth: 0,
              }}
            />
            <rect
              width={499}
              height={50}
              style={{
                fill: "rgb(216, 216, 216)",
                stroke: "rgb(0, 0, 0)",
                strokeWidth: 0,
              }}
              y={50}
            />
            <rect
              width={499}
              height={50}
              style={{
                fill: "rgb(216, 216, 216)",
                stroke: "rgb(0, 0, 0)",
                strokeWidth: 0,
              }}
              y={100}
            />
            <rect
              width={499}
              height={50}
              style={{
                fill: "rgb(216, 216, 216)",
                stroke: "rgb(0, 0, 0)",
                strokeWidth: 0,
              }}
              y={149}
            />
            <rect
              width={499}
              height={50}
              style={{
                fill: "rgb(216, 216, 216)",
                stroke: "rgb(0, 0, 0)",
                strokeWidth: 0,
              }}
              y={199}
            />
            <rect
              width={499}
              height={50}
              style={{
                fill: "rgb(216, 216, 216)",
                stroke: "rgb(0, 0, 0)",
                strokeWidth: 0,
              }}
              y={249}
            />
            <rect
              width={499}
              height={50}
              style={{
                fill: "rgb(216, 216, 216)",
                stroke: "rgb(0, 0, 0)",
                strokeWidth: 0,
              }}
              y={299}
            />
          </clipPath>
        </defs>
        <image
          href="data:image/jpeg;base64,"
          width={500}
          height={333}
          style={{
            clipPath: "url(#clip-bird)",
          }}
          transform="matrix(1.001902, 0, 0, 1.004198, -0.458112, 0)"
        />
      </svg>
      <svg
        id="turtle"
        xmlns="http://www.w3.org/2000/svg"
        viewBox="0 0 300 200"
        width={500}
        height={333}
        style={{ background: "black" }}
        onMouseEnter={handleMouseEnter}
        onMouseLeave={handleMouseLeave}
      >
        <defs>
          <clipPath id="clip-turtle">
            <ellipse
              style={{
                fill: "rgb(216, 216, 216)",
                stroke: "rgb(0, 0, 0)",
              }}
              cx={150}
              cy={112}
              rx={93}
              ry={105}
            />
          </clipPath>
        </defs>
        <image
          href="data:image/jpeg;base64,"
          width={300}
          height={225}
          opacity={0}
          style={{
            clipPath: "url(#clip-turtle)",
          }}
          transform="matrix(1, 0, 0, 0.888889, 0, 0)"
        />
      </svg>
    </div>
  );
}
